-- Restores both 374 definitions verbatim, collisions included, so history stays honest.
BEGIN;
CREATE OR REPLACE FUNCTION refs_create_accounting_settings_workflow(p_tenant uuid,p_entity uuid,p_period uuid,p_ids jsonb,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;snapshot jsonb;wid uuid:=gen_random_uuid();v bigint;payload jsonb;result jsonb;p accounting_period;history_hash text;event_at timestamptz;
BEGIN
 IF NOT refs_accounting_settings_safe_text(actor,1,300) OR NOT refs_accounting_settings_safe_text(p_reason,8,2000) OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_accounting_settings_create_hash(p_tenant,p_entity,p_period,p_ids,p_reason) THEN RAISE EXCEPTION 'Invalid accounting settings create command' USING ERRCODE='22023';END IF;
 PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');
 PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.CREATE');
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'ACCOUNTING_SETTINGS_CREATE:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='ACCOUNTING_SETTINGS_CREATE:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Accounting settings create idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ACCOUNTING_SETTINGS:'||p_tenant::text||':'||p_entity::text,0));
 PERFORM 1 FROM entity WHERE tenant_id=p_tenant AND entity_id=p_entity AND active FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings entity was not found or active' USING ERRCODE='P0002';END IF;
 SELECT * INTO p FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings period was not found' USING ERRCODE='P0002';END IF;IF p.ledger_code<>'PRIMARY' THEN RAISE EXCEPTION 'Accounting settings require a PRIMARY ledger period' USING ERRCODE='23514';END IF;IF EXISTS(SELECT 1 FROM accounting_period other WHERE other.tenant_id=p_tenant AND other.entity_id=p_entity AND other.ledger_code='PRIMARY' AND other.period_id<>p.period_id AND daterange(other.starts_on,other.ends_on,'[]')&&daterange(p.starts_on,p.ends_on,'[]')) THEN RAISE EXCEPTION 'Accounting settings PRIMARY period range overlaps another period' USING ERRCODE='23514';END IF;IF p.status<>'OPEN' THEN RAISE EXCEPTION 'Accounting settings workflow requires an OPEN target period' USING ERRCODE='55000';END IF;
 LOCK TABLE setting_snapshot IN SHARE MODE;
 IF EXISTS(SELECT 1 FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND status IN('ACTIVE','SUPERSEDED'))
  OR EXISTS(SELECT 1 FROM setting_snapshot s JOIN accounting_period p ON p.tenant_id=p_tenant AND p.entity_id=p_entity AND p.period_id=p_period WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND s.effective_from>=p.starts_on::timestamptz AND s.effective_from<p.ends_on::timestamptz+interval '1 day') THEN RAISE EXCEPTION 'Same-period accounting settings replacement is forbidden; choose a later target period' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND (s.snapshot->>'period_end' IS NULL OR s.snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR s.snapshot->>'period_end'>=p.starts_on::text))
  OR EXISTS(SELECT 1 FROM accounting_settings_workflow prior WHERE prior.tenant_id=p_tenant AND prior.entity_id=p_entity AND prior.status IN('ACTIVE','SUPERSEDED') AND (prior.canonical_parent_snapshot->>'period_end' IS NULL OR prior.canonical_parent_snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR prior.canonical_parent_snapshot->>'period_end'>=p.starts_on::text)) THEN RAISE EXCEPTION 'Accounting settings Draft must target a period strictly later than retained parent history' USING ERRCODE='55000';END IF;
 snapshot:=refs_accounting_settings_parent_snapshot(p_tenant,p_entity,p_period,p_ids);
 SELECT coalesce(max(version),0)+1 INTO v FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity;
 event_at:=clock_timestamp();
 INSERT INTO accounting_settings_workflow(accounting_settings_workflow_id,tenant_id,entity_id,period_id,version,child_setting_snapshot_ids,canonical_parent_snapshot,canonical_parent_hash,created_by,created_at) VALUES(wid,p_tenant,p_entity,p_period,v,p_ids,snapshot,refs_jsonb_hash(snapshot),actor,event_at);
 history_hash:=refs_accounting_settings_history_hash(p_tenant,wid,NULL,'DRAFT',0,actor,p_reason,NULL,event_at);
 payload:=jsonb_build_object('workflow_id',wid,'status','DRAFT','revision','0','version',v::text,'period_id',p_period,'canonical_parent_hash',refs_jsonb_hash(snapshot),'actor_id',actor,'reason',btrim(p_reason),'previous_event_hash',NULL,'history_event_hash',history_hash,'created_at',event_at);
 INSERT INTO accounting_settings_workflow_history(accounting_settings_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,previous_event_hash,event_hash,created_at) VALUES(wid,p_tenant,NULL,'DRAFT',0,actor,btrim(p_reason),NULL,history_hash,event_at);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_DRAFT_CREATED','ACCOUNTING_SETTINGS_WORKFLOW',wid,'CREATE',actor,'USER','ACCOUNTING.SETTINGS.WORKFLOW.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_WORKFLOW',wid,'ACCOUNTING_SETTINGS_DRAFT_CREATED',payload,refs_jsonb_hash(payload));
 result:=refs_accounting_settings_workflow_payload(p_tenant,p_entity,wid)||jsonb_build_object('idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=result,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN result;
END;$$;

CREATE OR REPLACE FUNCTION refs_transition_accounting_settings_workflow(p_tenant uuid,p_entity uuid,p_workflow uuid,p_action text,p_expected_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();action text:=upper(p_action);permission text;next_status text;idem idempotency_receipt;w accounting_settings_workflow;initial accounting_settings_workflow;p accounting_period;snapshot jsonb;payload jsonb;result jsonb;oldw accounting_settings_workflow;oldparent setting_snapshot;parent_id uuid:=gen_random_uuid();parent_version bigint;readback jsonb;target_start date;latest_parent_period_end date;latest_workflow_period_end date;previous_hash text;history_hash text;old_previous_hash text;old_history_hash text;event_at timestamptz;old_event_at timestamptz;
BEGIN
 IF action IS NULL OR action NOT IN('SUBMIT','REVIEW','APPROVE','ACTIVATE') OR NOT refs_accounting_settings_safe_text(actor,1,300) OR p_expected_revision IS NULL OR p_expected_revision<0 OR NOT refs_accounting_settings_safe_text(p_reason,8,2000) OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_accounting_settings_transition_hash(p_tenant,p_entity,p_workflow,action,p_expected_revision,p_reason) THEN RAISE EXCEPTION 'Invalid accounting settings transition command' USING ERRCODE='22023';END IF;
 permission:='ACCOUNTING.SETTINGS.WORKFLOW.'||action;PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');PERFORM refs_assert_scope(p_tenant,p_entity,permission);
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'ACCOUNTING_SETTINGS_'||action||':'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='ACCOUNTING_SETTINGS_'||action||':'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Accounting settings transition idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ACCOUNTING_SETTINGS:'||p_tenant::text||':'||p_entity::text,0));
 PERFORM 1 FROM entity WHERE tenant_id=p_tenant AND entity_id=p_entity AND active FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings entity was not found or active' USING ERRCODE='P0002';END IF;
 SELECT * INTO initial FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND accounting_settings_workflow_id=p_workflow;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings workflow was not found' USING ERRCODE='P0002';END IF;
 SELECT * INTO p FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=initial.period_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings period was not found' USING ERRCODE='P0002';END IF;IF p.ledger_code<>'PRIMARY' THEN RAISE EXCEPTION 'Accounting settings require a PRIMARY ledger period' USING ERRCODE='23514';END IF;IF EXISTS(SELECT 1 FROM accounting_period other WHERE other.tenant_id=p_tenant AND other.entity_id=p_entity AND other.ledger_code='PRIMARY' AND other.period_id<>p.period_id AND daterange(other.starts_on,other.ends_on,'[]')&&daterange(p.starts_on,p.ends_on,'[]')) THEN RAISE EXCEPTION 'Accounting settings PRIMARY period range overlaps another period' USING ERRCODE='23514';END IF;IF p.status<>'OPEN' THEN RAISE EXCEPTION 'Accounting settings transition requires the target period to remain OPEN' USING ERRCODE='55000';END IF;
 SELECT * INTO w FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND accounting_settings_workflow_id=p_workflow FOR UPDATE;
 SELECT event_hash INTO previous_hash FROM accounting_settings_workflow_history WHERE tenant_id=p_tenant AND accounting_settings_workflow_id=p_workflow AND revision=w.revision;
 IF previous_hash IS NULL THEN RAISE EXCEPTION 'Accounting settings history chain is incomplete' USING ERRCODE='23514';END IF;
 LOCK TABLE setting_snapshot IN SHARE ROW EXCLUSIVE MODE;snapshot:=refs_accounting_settings_parent_snapshot(p_tenant,p_entity,w.period_id,w.child_setting_snapshot_ids);
 IF snapshot IS DISTINCT FROM w.canonical_parent_snapshot OR refs_jsonb_hash(snapshot)<>w.canonical_parent_hash THEN RAISE EXCEPTION 'Accounting settings source evidence changed' USING ERRCODE='40001';END IF;
 target_start:=(snapshot->>'period_start')::date;
 SELECT max(CASE WHEN s.snapshot->>'period_end'~'^\d{4}-\d{2}-\d{2}$' THEN (s.snapshot->>'period_end')::date ELSE 'infinity'::date END) INTO latest_parent_period_end FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED');
 SELECT max(CASE WHEN prior.canonical_parent_snapshot->>'period_end'~'^\d{4}-\d{2}-\d{2}$' THEN (prior.canonical_parent_snapshot->>'period_end')::date ELSE 'infinity'::date END) INTO latest_workflow_period_end FROM accounting_settings_workflow prior WHERE prior.tenant_id=p_tenant AND prior.entity_id=p_entity AND prior.accounting_settings_workflow_id<>p_workflow AND prior.status IN('ACTIVE','SUPERSEDED');
 IF (latest_parent_period_end IS NOT NULL AND latest_parent_period_end>=target_start) OR (latest_workflow_period_end IS NOT NULL AND latest_workflow_period_end>=target_start) THEN RAISE EXCEPTION 'Accounting settings transition must remain strictly later than all retained parent history' USING ERRCODE='55000';END IF;
 next_status:=CASE action WHEN 'SUBMIT' THEN 'SUBMITTED' WHEN 'REVIEW' THEN 'REVIEWED' WHEN 'APPROVE' THEN 'APPROVED' ELSE 'ACTIVE' END;
 IF w.revision<>p_expected_revision THEN RAISE EXCEPTION 'Accounting settings revision conflict' USING ERRCODE='40001';END IF;
 IF (action='SUBMIT' AND w.status<>'DRAFT') OR(action='REVIEW' AND w.status<>'SUBMITTED') OR(action='APPROVE' AND w.status<>'REVIEWED') OR(action='ACTIVATE' AND w.status<>'APPROVED') THEN RAISE EXCEPTION 'Accounting settings status conflict' USING ERRCODE='40001';END IF;
 IF (action='SUBMIT' AND actor=w.created_by) OR(action='REVIEW' AND actor=ANY(ARRAY[w.created_by,w.submitted_by])) OR(action='APPROVE' AND actor=ANY(ARRAY[w.created_by,w.submitted_by,w.reviewed_by])) OR(action='ACTIVATE' AND actor=ANY(ARRAY[w.created_by,w.submitted_by,w.reviewed_by,w.approved_by])) THEN RAISE EXCEPTION 'Accounting settings separation of duties violation' USING ERRCODE='42501';END IF;
 IF action='ACTIVATE' THEN
  SELECT * INTO oldw FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='ACTIVE' FOR UPDATE;
  IF oldw.accounting_settings_workflow_id IS NOT NULL THEN
   IF (snapshot->>'period_start')::date<=(oldw.canonical_parent_snapshot->>'period_start')::date THEN RAISE EXCEPTION 'Accounting settings replacement must target a strictly later period' USING ERRCODE='55000';END IF;
   SELECT * INTO oldparent FROM setting_snapshot WHERE tenant_id=p_tenant AND entity_id=p_entity AND setting_snapshot_id=oldw.legacy_parent_setting_snapshot_id FOR UPDATE;
   IF oldparent.status<>'APPROVED' OR oldparent.effective_from>=(snapshot->>'period_start')::date::timestamptz OR(oldparent.effective_to IS NOT NULL AND oldparent.effective_to<(snapshot->>'period_start')::date::timestamptz) THEN RAISE EXCEPTION 'Prior active parent cannot be retired safely' USING ERRCODE='55000';END IF;
   IF actor=ANY(ARRAY[oldparent.created_by,oldparent.approved_by]) THEN RAISE EXCEPTION 'Activator cannot retire a parent they created or approved' USING ERRCODE='42501';END IF;
   IF oldparent.snapshot_hash<>refs_jsonb_hash(oldparent.snapshot) OR oldparent.snapshot->>'period_end' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Prior active parent period evidence is invalid' USING ERRCODE='23514';END IF;
   IF target_start<=(oldparent.snapshot->>'period_end')::date THEN RAISE EXCEPTION 'Accounting settings replacement cannot truncate a prior period' USING ERRCODE='55000';END IF;
   INSERT INTO accounting_settings_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,oldw.accounting_settings_workflow_id,'PARENT_RETIRE');
   PERFORM set_config('refs.config_retire','authorized',true);
   UPDATE setting_snapshot SET status='RETIRED',effective_to=(snapshot->>'period_start')::date::timestamptz,retired_by=actor,retired_at=clock_timestamp(),retire_reason='Superseded by forward accounting settings activation',lifecycle_revision=lifecycle_revision+1 WHERE setting_snapshot_id=oldparent.setting_snapshot_id;
   PERFORM set_config('refs.config_retire','',true);
   DELETE FROM accounting_settings_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND accounting_settings_workflow_id=oldw.accounting_settings_workflow_id AND operation='PARENT_RETIRE';
   payload:=jsonb_build_object('snapshot_id',oldparent.setting_snapshot_id,'status','RETIRED','effective_to',snapshot->>'period_start','workflow_id',p_workflow);
   INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONFIG_SNAPSHOT_RETIRED','SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'RETIRE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
   INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'CONFIG_SNAPSHOT_RETIRED',payload,refs_jsonb_hash(payload));
   INSERT INTO accounting_settings_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,oldw.accounting_settings_workflow_id,'SUPERSEDED');
   old_event_at:=clock_timestamp();
   UPDATE accounting_settings_workflow SET status='SUPERSEDED',revision=revision+1,superseded_by_workflow_id=p_workflow,superseded_at=old_event_at WHERE accounting_settings_workflow_id=oldw.accounting_settings_workflow_id;
   DELETE FROM accounting_settings_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND accounting_settings_workflow_id=oldw.accounting_settings_workflow_id AND operation='SUPERSEDED';
   SELECT event_hash INTO old_previous_hash FROM accounting_settings_workflow_history WHERE tenant_id=p_tenant AND accounting_settings_workflow_id=oldw.accounting_settings_workflow_id AND revision=oldw.revision;
   IF old_previous_hash IS NULL THEN RAISE EXCEPTION 'Prior accounting settings history chain is incomplete' USING ERRCODE='23514';END IF;
   old_history_hash:=refs_accounting_settings_history_hash(p_tenant,oldw.accounting_settings_workflow_id,'ACTIVE','SUPERSEDED',oldw.revision+1,actor,p_reason,old_previous_hash,old_event_at);
   payload:=jsonb_build_object('workflow_id',oldw.accounting_settings_workflow_id,'from_status','ACTIVE','status','SUPERSEDED','revision',(oldw.revision+1)::text,'actor_id',actor,'reason',btrim(p_reason),'previous_event_hash',old_previous_hash,'history_event_hash',old_history_hash,'superseded_by_workflow_id',p_workflow,'retired_parent_setting_snapshot_id',oldparent.setting_snapshot_id,'created_at',old_event_at);
   INSERT INTO accounting_settings_workflow_history(accounting_settings_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,previous_event_hash,event_hash,created_at) VALUES(oldw.accounting_settings_workflow_id,p_tenant,'ACTIVE','SUPERSEDED',oldw.revision+1,actor,btrim(p_reason),old_previous_hash,old_history_hash,old_event_at);
   INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_SUPERSEDED','ACCOUNTING_SETTINGS_WORKFLOW',oldw.accounting_settings_workflow_id,'SUPERSEDE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
   INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_WORKFLOW',oldw.accounting_settings_workflow_id,'ACCOUNTING_SETTINGS_SUPERSEDED',payload,refs_jsonb_hash(payload));
  ELSE
   SELECT * INTO oldparent FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status='APPROVED' AND s.effective_from<=(snapshot->>'period_start')::date::timestamptz AND(s.effective_to IS NULL OR s.effective_to>(snapshot->>'period_start')::date::timestamptz) FOR UPDATE;
   IF oldparent.setting_snapshot_id IS NOT NULL THEN
    IF oldparent.effective_from>=(snapshot->>'period_start')::date::timestamptz THEN RAISE EXCEPTION 'Same-period legacy settings replacement is forbidden' USING ERRCODE='55000';END IF;
    IF actor=ANY(ARRAY[oldparent.created_by,oldparent.approved_by]) THEN RAISE EXCEPTION 'Activator cannot retire a parent they created or approved' USING ERRCODE='42501';END IF;
    IF oldparent.snapshot_hash<>refs_jsonb_hash(oldparent.snapshot) OR oldparent.snapshot->>'period_end' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Legacy parent period evidence is invalid' USING ERRCODE='23514';END IF;
    IF target_start<=(oldparent.snapshot->>'period_end')::date THEN RAISE EXCEPTION 'Accounting settings replacement cannot truncate a prior period' USING ERRCODE='55000';END IF;
    PERFORM set_config('refs.config_retire','authorized',true);
    UPDATE setting_snapshot SET status='RETIRED',effective_to=(snapshot->>'period_start')::date::timestamptz,retired_by=actor,retired_at=clock_timestamp(),retire_reason='Adopted by forward accounting settings workflow activation',lifecycle_revision=lifecycle_revision+1 WHERE setting_snapshot_id=oldparent.setting_snapshot_id;
    PERFORM set_config('refs.config_retire','',true);
    payload:=jsonb_build_object('snapshot_id',oldparent.setting_snapshot_id,'status','RETIRED','effective_to',snapshot->>'period_start','workflow_id',p_workflow);
    INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONFIG_SNAPSHOT_RETIRED','SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'RETIRE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
    INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'CONFIG_SNAPSHOT_RETIRED',payload,refs_jsonb_hash(payload));
   END IF;
  END IF;
  SELECT coalesce(max(version),0)+1 INTO parent_version FROM setting_snapshot WHERE tenant_id=p_tenant AND family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND scope_type='ENTITY' AND scope_key=p_entity::text;
  INSERT INTO setting_snapshot(setting_snapshot_id,tenant_id,entity_id,family,scope_type,scope_key,version,effective_from,effective_to,status,snapshot,snapshot_hash,created_by,approved_by,approved_at)
   VALUES(parent_id,p_tenant,p_entity,'AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1','ENTITY',p_entity::text,parent_version,(snapshot->>'period_start')::date::timestamptz,NULL,'APPROVED',snapshot,refs_jsonb_hash(snapshot),w.created_by,w.approved_by,w.approved_at);
  readback:=refs_validate_accounting_settings_activation_snapshot(p_tenant,p_entity,w.period_id);
  IF readback->>'settings_snapshot_id'<>parent_id::text OR readback->>'settings_hash'<>refs_jsonb_hash(snapshot) THEN RAISE EXCEPTION 'Activated settings failed authoritative readback' USING ERRCODE='23514';END IF;
  payload:=jsonb_build_object('setting_snapshot_id',parent_id,'tenant_id',p_tenant,'entity_id',p_entity,'family','AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1','version',parent_version::text,'effective_from',target_start::text,'snapshot_hash',refs_jsonb_hash(snapshot),'workflow_id',p_workflow,'approved_by',w.approved_by,'activated_by',actor);
  INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONFIG_SNAPSHOT_APPROVED','SETTING_SNAPSHOT',parent_id,'APPROVE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
  INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'SETTING_SNAPSHOT',parent_id,'CONFIG_SNAPSHOT_APPROVED',payload,refs_jsonb_hash(payload));
 END IF;
 event_at:=clock_timestamp();
 INSERT INTO accounting_settings_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_workflow,next_status);
 UPDATE accounting_settings_workflow SET status=next_status,revision=revision+1,
  submitted_by=CASE WHEN action='SUBMIT' THEN actor ELSE submitted_by END,submitted_at=CASE WHEN action='SUBMIT' THEN event_at ELSE submitted_at END,
  reviewed_by=CASE WHEN action='REVIEW' THEN actor ELSE reviewed_by END,reviewed_at=CASE WHEN action='REVIEW' THEN event_at ELSE reviewed_at END,
  approved_by=CASE WHEN action='APPROVE' THEN actor ELSE approved_by END,approved_at=CASE WHEN action='APPROVE' THEN event_at ELSE approved_at END,
  activated_by=CASE WHEN action='ACTIVATE' THEN actor ELSE activated_by END,activated_at=CASE WHEN action='ACTIVATE' THEN event_at ELSE activated_at END,
  legacy_parent_setting_snapshot_id=CASE WHEN action='ACTIVATE' THEN parent_id ELSE legacy_parent_setting_snapshot_id END WHERE accounting_settings_workflow_id=p_workflow;
 DELETE FROM accounting_settings_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND accounting_settings_workflow_id=p_workflow AND operation=next_status;
 history_hash:=refs_accounting_settings_history_hash(p_tenant,p_workflow,w.status,next_status,w.revision+1,actor,p_reason,previous_hash,event_at);
 payload:=jsonb_build_object('workflow_id',p_workflow,'from_status',w.status,'status',next_status,'revision',(w.revision+1)::text,'actor_id',actor,'reason',btrim(p_reason),'previous_event_hash',previous_hash,'history_event_hash',history_hash,'legacy_parent_setting_snapshot_id',CASE WHEN action='ACTIVATE' THEN parent_id ELSE NULL END,'canonical_parent_hash',w.canonical_parent_hash,'created_at',event_at);
 INSERT INTO accounting_settings_workflow_history(accounting_settings_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,previous_event_hash,event_hash,created_at) VALUES(p_workflow,p_tenant,w.status,next_status,w.revision+1,actor,btrim(p_reason),previous_hash,history_hash,event_at);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_'||action,'ACCOUNTING_SETTINGS_WORKFLOW',p_workflow,action,actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_WORKFLOW',p_workflow,'ACCOUNTING_SETTINGS_'||action,payload,refs_jsonb_hash(payload));
 result:=refs_accounting_settings_workflow_payload(p_tenant,p_entity,p_workflow)||jsonb_build_object('idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=result,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN result;
END;$$;
COMMIT;
